mapper.select:
select matched_user_id
from match_relation
where user_id = #{userId}

mapper.insert:
insert into match_relation (user_id, status, created_at)
select #{userId}, 0, now()
where not exists (
    select 1 from match_relation where user_id = #{userId}
)

mapper.select:
select matched_user_id,created_at,status
from match_relation
where user_id = #{userId}

mapper.delete:
delete from match_relation
where user_id = #{userId}
and matched_user_id = #{matchedUserId}
and status = 1
